/* شعارات خاصة بالمشتركين: يظهر الشعار فقط لصاحب الكود، ويعمل بدون إنترنت.
   الكود لا يُخزَّن هنا؛ فقط بصمته (PBKDF2) حتى لا يمكن استخراجه من الملف. */
(function () {
  'use strict';
  var BRANDS = {
    "1265d32bea6f7767be92f98e5e322d2e": { name: "Mustafa Al hafiz", logoDark: "data:image/png;base64,", logo: "data:image/png;base64," }
  };
  var lastKey = null;
  function hex(buf) { return Array.prototype.map.call(new Uint8Array(buf), function (b) { return ('0' + b.toString(16)).slice(-2); }).join(''); }
  function keyHash(key) {
    var enc = new TextEncoder();
    return crypto.subtle.importKey('raw', enc.encode(String(key).trim().toLowerCase()), 'PBKDF2', false, ['deriveBits'])
      .then(function (k) { return crypto.subtle.deriveBits({ name: 'PBKDF2', salt: enc.encode('moelab-brand-v1'), iterations: 60000, hash: 'SHA-256' }, k, 128); })
      .then(hex);
  }
  function currentKey() {
    try { var l = JSON.parse(localStorage.getItem('moe_offline_license') || 'null'); return l && l.key ? String(l.key) : ''; } catch (e) { return ''; }
  }
  function isLight(el) {
    try {
      var m = getComputedStyle(el).backgroundColor.match(/[\d.]+/g);
      if (!m) return false;
      var a = m.length > 3 ? parseFloat(m[3]) : 1; if (a === 0) return false;
      return (0.299 * m[0] + 0.587 * m[1] + 0.114 * m[2]) > 150;
    } catch (e) { return false; }
  }
  function remove() { var o = document.getElementById('brandLogoWrap'); if (o) o.remove(); }
  function show(b) {
    var hd = document.querySelector('header');
    if (!hd) return;
    remove();
    var w = document.createElement('div');
    w.id = 'brandLogoWrap';
    w.style.cssText = 'display:flex;align-items:center;gap:12px;margin-inline-end:14px;padding-inline-end:14px;border-inline-end:1px solid #2a3b57;flex-shrink:0';
    var im = document.createElement('img');
    var light = isLight(hd);
    im.src = light && b.logoDark ? b.logoDark : b.logo; im.alt = b.name;
    if (light) w.style.borderInlineEndColor = '#e6d6bd';
    im.style.cssText = 'height:40px;width:auto;max-width:42vw;display:block;object-fit:contain';
    w.appendChild(im);
    var first = hd.firstElementChild;
    var grp = document.createElement('div');
    grp.style.cssText = 'display:flex;align-items:center;min-width:0';
    hd.insertBefore(grp, first);
    grp.appendChild(w); grp.appendChild(first);
  }
  function check() {
    var k = currentKey();
    if (k === lastKey) return;
    lastKey = k;
    if (!k || !window.crypto || !crypto.subtle) { remove(); return; }
    keyHash(k).then(function (h) {
      if (currentKey() !== k) return;
      if (BRANDS[h]) show(BRANDS[h]); else remove();
    }).catch(function () { remove(); });
  }
  check();
  setInterval(check, 1500);
})();
